package com.lexiscan.auth; import com.lexiscan.config.AppProperties; import com.lexiscan.user.User; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
@Service public class JwtService { private final AppProperties props; public JwtService(AppProperties p){props=p;} private SecretKey key(){return Keys.hmacShaKeyFor(props.jwt().secret().getBytes(StandardCharsets.UTF_8));} public String issue(User u){var now=Instant.now();return Jwts.builder().subject(u.getId().toString()).claim("role",u.getRole().name()).issuedAt(Date.from(now)).expiration(Date.from(now.plus(Duration.ofMinutes(props.jwt().expirationMinutes())))).signWith(key()).compact();} public UUID subject(String token){return UUID.fromString(Jwts.parser().verifyWith(key()).build().parseSignedClaims(token).getPayload().getSubject());} }
